// Bluetooth lab B1 Listen.  uv run pio run -d labs/ble-lab-b1 -e ble-lab-b1 -t upload
// The board only listens: every Bluetooth LE device around you shouts short "advertising" packets
// on three radio channels, many times a second, whether anyone listens or not. B1 hears them all,
// guesses what each one is, and takes the packets apart byte by byte. Nothing is ever sent to them.
//
// Wiring: the screen from lesson 03. The push button on GPIO 5 is optional (it does what BOOT does).
//
// Views: radar · list · inspect · air   (click = next, double-click = the action in the footer,
//        long press = pause or resume the scan)
// Serial: help lists the commands. Shared code: kit/lib/ble-kit.
#include "b1_views.h"
#include "ble_lab.h"
#include "listener.h"

namespace {

b1::Listener ears;
b1::AirHistory history;
b1::Pick pick;
ble::Heard rows[ble::ScanTable::kMax];
int rowCount = 0;

// The picked device in this frame's rows, or nullptr when it went quiet.
const ble::Heard *picked() {
  for (int i = 0; i < rowCount; i++)
    if (pick.matches(rows[i])) return &rows[i];
  return nullptr;
}

void pickIndex(int i) {
  if (i < 0 || i >= rowCount) return;
  pick.take(rows[i]);
  char addr[18];
  rows[i].addrText(addr, sizeof(addr));
  BLE_NOTE(Info, "picked %d: %s %s", i + 1, rows[i].label(), addr);
}

// ---- Views ------------------------------------------------------------------------------------

void drawRadar(BleLab &, FrameBuffer &fb, float t) { b1v::radar(fb, rows, rowCount, pick, ears.settings, ears.scanning(), history.latest(), t); }
void drawList(BleLab &, FrameBuffer &fb, float) { b1v::list(fb, rows, rowCount, pick); }
void drawInspect(BleLab &, FrameBuffer &fb, float) { b1v::inspect(fb, picked(), ears.settings); }
void drawAir(BleLab &, FrameBuffer &fb, float) { b1v::air(fb, history, rows, rowCount, ears.settings, ears.scanning()); }

const BleView kViews[] = {
    {"radar", drawRadar, "next"},
    {"list", drawList, "next"},
    {"inspect", drawInspect, "watch"},
    {"air", drawAir, "mode"},
};

// ---- Commands ---------------------------------------------------------------------------------

void cmdScan(BleLab &lab, const String &, const String &lower) {
  const bool on = lower.isEmpty() ? !ears.scanning() : lower == "on";
  if (!lower.isEmpty() && lower != "on" && lower != "off") return lab.warn("scan | scan on | scan off");
  on ? ears.start() : ears.stop();
}

void cmdMode(BleLab &lab, const String &, const String &lower) {
  if (!lower.isEmpty() && lower != "active" && lower != "passive") return lab.warn("mode | mode active | mode passive");
  ears.settings.active = lower.isEmpty() ? !ears.settings.active : lower == "active";
  ears.start();
}

void cmdTiming(BleLab &lab, const String &arg, const String &) {
  const int sp = arg.indexOf(' ');
  long interval = 0, window = 0;
  if (sp < 0 || !BleLab::number(arg.substring(0, sp), 10, 10240, interval) || !BleLab::number(arg.substring(sp + 1), 10, interval, window))
    return lab.warn("timing <interval ms> <window ms>, 10-10240, window <= interval (default 100 100)");
  ears.settings.intervalMs = uint16_t(interval);
  ears.settings.windowMs = uint16_t(window);
  ears.start();
}

void cmdNear(BleLab &lab, const String &arg, const String &lower) {
  long dbm = 0;
  if (lower == "off") ears.settings.nearDbm = -127;
  else if (BleLab::number(arg, -100, -20, dbm)) ears.settings.nearDbm = int(dbm);
  else return lab.warn("near <dBm> (e.g. near -70) | near off");
  if (ears.settings.nearDbm == -127) BLE_NOTE(Info, "showing every device");
  else BLE_NOTE(Info, "showing devices stronger than %d dBm", ears.settings.nearDbm);
}

void cmdPick(BleLab &lab, const String &arg, const String &) {
  long n = 0;
  if (!BleLab::number(arg, 1, std::max(rowCount, 1), n)) return lab.warn("pick <1-%d>: the number on the list view", rowCount);
  pickIndex(n - 1);
  lab.showView("inspect");
}

void cmdNext(BleLab &, const String &, const String &) {
  if (rowCount == 0) return;
  int at = -1;
  for (int i = 0; i < rowCount; i++)
    if (pick.matches(rows[i])) at = i;
  pickIndex((at + 1) % rowCount);
}

void cmdWatch(BleLab &lab, const String &, const String &lower) {
  if (lower == "off" || ears.watching()) {
    ears.watch(b1::Pick{});
    return BLE_NOTE(Info, "watch off");
  }
  if (!picked()) return lab.warn("pick a device first (list view, double-click; or pick <n>)");
  ears.watch(pick);
  BLE_NOTE(Info, "watching %s: one line per packet, see the gaps", picked()->label());
}

void cmdList(BleLab &, const String &, const String &) {
  Serial.printf("%d devices heard in the last 30 s (strongest first):\n", rowCount);
  Serial.println("  #  dBm  ~m     kind            address            type           packets  name / maker");
  for (int i = 0; i < rowCount; i++) {
    const ble::Heard &h = rows[i];
    char addr[18];
    h.addrText(addr, sizeof(addr));
    Serial.printf("%3d  %4d  %4.1f  %-14s  %s  %-14s %7lu  %s%s\n", i + 1, int(h.rssiAvg), ad::distanceMeters(int(h.rssiAvg), ears.settings.rssiAt1m),
                  ad::kindName(h.kind), addr, ad::addrKindName(h.addrKind()), static_cast<unsigned long>(h.packets), h.label(),
                  h.connectable ? "" : "  (broadcast only)");
  }
}

void printBytes(const char *what, const uint8_t *p, uint8_t n) {
  Serial.printf("  %s, %u of 31 bytes:\n   ", what, n);
  const ad::Parsed ps = ad::split(p, n);
  for (int f = 0; f < ps.count; f++) {
    const ad::Field &fl = ps.fields[f];
    Serial.printf("  [%02X %02X |", fl.len + 1, fl.type);
    for (int i = 0; i < fl.len; i++) Serial.printf(" %02X", p[fl.offset + i]);
    Serial.printf("] %s\n   ", ad::typeName(fl.type));
  }
  if (ps.malformed) Serial.print("  malformed: a length runs past the end");
  Serial.println();
}

void cmdBytes(BleLab &lab, const String &, const String &) {
  const ble::Heard *h = picked();
  if (!h) return lab.warn("pick a device first");
  char addr[18];
  h->addrText(addr, sizeof(addr));
  Serial.printf("%s  %s (%s)\n", h->label(), addr, ad::addrKindName(h->addrKind()));
  printBytes("advertisement", h->adv, h->advLen);
  if (h->rspLen) printBytes("scan response", h->rsp, h->rspLen);
  else Serial.println(ears.settings.active ? "  no scan response (it doesn't send one)" : "  scan response: switch to mode active to ask for it");
}

void cmdCalib(BleLab &lab, const String &, const String &) {
  const ble::Heard *h = picked();
  if (!h) return lab.warn("pick your phone first, hold it 1 m from the board, then calib");
  ears.settings.rssiAt1m = int(h->rssiAvg);
  BLE_NOTE(Good, "1 m = %d dBm now: distances use it", ears.settings.rssiAt1m);
}

void cmdClear(BleLab &, const String &, const String &) {
  ears.table.clear();
  pick = b1::Pick{};
  BLE_NOTE(Info, "table cleared");
}

const BleCommand kCommands[] = {
    {"scan", "[on|off]", "listen, or pause (alone: toggle; long press too)", cmdScan},
    {"mode", "[active|passive]", "active asks every device for its scan response", cmdMode},
    {"timing", "<interval> <window>", "scan interval and window in ms (default 100 100)", cmdTiming},
    {"near", "<dBm>|off", "hide devices weaker than this, e.g. near -70", cmdNear},
    {"list", "", "print every device heard in the last 30 s", cmdList},
    {"pick", "<n>", "inspect device n from the list", cmdPick},
    {"next", "", "pick the next device", cmdNext},
    {"bytes", "", "the picked device's packets, structure by structure", cmdBytes},
    {"watch", "[off]", "one line per packet of the picked device (its interval)", cmdWatch},
    {"calib", "", "the picked device is 1 m away: use its RSSI as 1 m", cmdCalib},
    {"clear", "", "forget every device", cmdClear},
};

// ---- Hooks ------------------------------------------------------------------------------------

void setup(BleLab &) { ears.begin(); }

void tick(BleLab &) {
  rowCount = ears.table.snapshot(rows, ble::ScanTable::kMax, 30000, ears.settings.nearDbm);
  int recent = 0;  // "in range" = heard in the last 10 s
  for (int i = 0; i < rowCount; i++) recent += millis() - rows[i].lastSeen < 10000;
  history.tick(ears.table, recent);
  if (!pick.set && rowCount) pick.take(rows[0]);
}

const BleLabSpec kSpec{
    "ble-lab-b1", "B1", "Listen", "Bench B1", kViews, sizeof(kViews) / sizeof(kViews[0]), 0,
    kCommands, sizeof(kCommands) / sizeof(kCommands[0]), setup, tick, nullptr, "scan",
};

BleLab lab(kSpec);

}  // namespace

void setup() { lab.begin(); }

void loop() { lab.loop(); }

// B1's four screens (320 x 170):
//   radar    every device as a blip: distance from its signal, colour = what it probably is
//   list     the strongest devices with name, address type, signal and age
//   inspect  one device's packets byte by byte, each AD structure in its own colour, decoded
//   air      packets per second over the last minute, how many devices, address types
#pragma once

#include <math.h>

#include "ad_format.h"
#include "ble_views.h"
#include "listener.h"

namespace b1v {

using namespace bv;

inline uint16_t kindColour(ad::Kind k) {
  switch (k) {
    case ad::Kind::Phone: return kBlue;
    case ad::Kind::Computer: return rgb(120, 200, 255);
    case ad::Kind::Audio: return pal::amber;
    case ad::Kind::Wearable: return rgb(255, 120, 200);
    case ad::Kind::Input: return pal::teal;
    case ad::Kind::Beacon: return kViolet;
    case ad::Kind::Tag: return pal::coral;
    case ad::Kind::Tv: return rgb(200, 200, 120);
    case ad::Kind::Bench: return rgb(120, 255, 140);
    default: return pal::muted;
  }
}

inline const char *addrShort(ad::AddrKind k) {
  static const char *const names[] = {"pub", "static", "rpa", "nrpa"};
  return names[static_cast<int>(k)];
}

// Same address = same angle, so a blip only moves in and out as its signal changes.
inline float angleOf(const ble::Heard &h) {
  uint32_t x = 2166136261u;
  for (int i = 0; i < 6; i++) x = (x ^ h.addr[i]) * 16777619u;
  return (x % 3600) / 3600.0f * 6.2832f;
}

// Distance in metres to radar pixels, on a log scale: 0.3 m near the middle, 20 m at the rim.
inline int radarRadius(float meters, int rim) {
  const float k = log10f(1 + fminf(meters, 20.0f)) / log10f(21.0f);
  return int(k * rim);
}

inline void radar(FrameBuffer &fb, const ble::Heard *rows, int n, const b1::Pick &pick, const b1::Settings &set, bool scanning, uint16_t pps, float t) {
  const int cx = 82, cy = 98, rim = 64;
  for (float m : {1.0f, 3.0f, 10.0f}) {
    const int r = radarRadius(m, rim);
    fb.drawCircle(cx, cy, r, pal::dim);
    char lbl[16];
    snprintf(lbl, sizeof(lbl), "%gm", m);
    small(fb, cx + r - 6, cy - 9, pal::dim, lbl);
  }
  fb.drawCircle(cx, cy, rim, pal::dim);
  fb.fillCircle(cx, cy, 3, kBlue);  // us
  const float sweep = fmodf(t * 1.6f, 6.2832f);
  if (scanning)
    for (int i = 0; i < 14; i++) {
      const float a = sweep - i * 0.04f;
      fb.drawLine(cx, cy, cx + int(cosf(a) * rim), cy + int(sinf(a) * rim), mix(pal::teal, pal::night, uint8_t(60 + i * 14)));
    }
  const uint32_t now = millis();
  for (int i = 0; i < n; i++) {
    const ble::Heard &h = rows[i];
    const float a = angleOf(h);
    const int r = radarRadius(ad::distanceMeters(int(h.rssiAvg), set.rssiAt1m), rim);
    const int x = cx + int(cosf(a) * r), y = cy + int(sinf(a) * r);
    // Brighter right after the sweep passes it, dimmer when it hasn't been heard for a while.
    float behind = fmodf(sweep - a + 6.2832f, 6.2832f);
    const uint8_t glow = scanning ? uint8_t(fmaxf(0, 1 - behind / 2.5f) * 120) : 0;
    const uint32_t age = now - h.lastSeen;
    uint16_t c = mix(kindColour(h.kind), pal::ink, glow);
    if (age > 5000) c = mix(c, pal::night, 170);
    const int size = h.rssiAvg > -60 ? 4 : h.rssiAvg > -75 ? 3 : 2;
    fb.fillCircle(x, y, size, c);
    if (pick.matches(h)) fb.drawCircle(x, y, size + 4 + int(sinf(t * 6) * 1.5f), pal::ink);
  }
  // Right: a short legend with the nearest five.
  char v[40];
  snprintf(v, sizeof(v), "%d devices", n);
  bold(fb, 170, 50, pal::ink, v);
  snprintf(v, sizeof(v), "%u packets/s  %s", pps, scanning ? (set.active ? "active" : "passive") : "paused");
  small(fb, 170, 56, scanning ? pal::teal : pal::amber, v);
  for (int i = 0; i < n && i < 6; i++) {
    const ble::Heard &h = rows[i];
    const int y = 72 + i * 14;
    fb.fillCircle(174, y + 3, 3, kindColour(h.kind));
    char label[15];
    strlcpy(label, h.label(), sizeof(label));
    small(fb, 182, y, pick.matches(h) ? pal::ink : pal::muted, label);
    const float d = ad::distanceMeters(int(h.rssiAvg), set.rssiAt1m);
    snprintf(v, sizeof(v), d < 10 ? "%.1fm" : "%.0fm", d);
    small(fb, 284, y, pal::muted, v);
  }
  if (n == 0) small(fb, 170, 76, pal::muted, scanning ? "listening..." : "long press: scan on");
}

inline void list(FrameBuffer &fb, const ble::Heard *rows, int n, const b1::Pick &pick) {
  small(fb, 6, 34, pal::dim, "#  name / maker        addr    dBm         age");
  const uint32_t now = millis();
  for (int i = 0; i < n && i < 9; i++) {
    const ble::Heard &h = rows[i];
    const int y = 46 + i * 12;
    const bool sel = pick.matches(h);
    if (sel) fb.fillRect(0, y - 2, kW, 12, kPanel);
    char v[24];
    snprintf(v, sizeof(v), "%d", i + 1);
    small(fb, 6, y, pal::muted, v);
    fb.fillRect(20, y, 6, 7, kindColour(h.kind));
    char label[19];
    strlcpy(label, h.label(), sizeof(label));
    small(fb, 30, y, sel ? pal::ink : pal::muted, label);
    small(fb, 144, y, h.addrKind() == ad::AddrKind::Resolvable ? kViolet : pal::muted, addrShort(h.addrKind()));
    snprintf(v, sizeof(v), "%d", int(h.rssiAvg));
    small(fb, 186, y, rssiColour(int(h.rssiAvg)), v);
    const int w = std::max(0, std::min(60, (int(h.rssiAvg) + 100) * 60 / 60));
    fb.fillRect(210, y + 1, w, 5, rssiColour(int(h.rssiAvg)));
    snprintf(v, sizeof(v), "%lus", static_cast<unsigned long>((now - h.lastSeen) / 1000));
    small(fb, 290, y, pal::muted, v);
  }
  if (n == 0) small(fb, 6, 60, pal::muted, "No devices yet.");
}

// The colour of AD structure i (cycled), shared by the bytes and their meaning below.
inline uint16_t fieldColour(int i) {
  static const uint16_t c[] = {kBlue, pal::amber, pal::teal, kViolet, pal::coral, rgb(120, 255, 140)};
  return c[i % 6];
}

// One packet as 31 little cells, one per byte: the colour says which AD structure it belongs
// to; the length and type bytes are darker than the data.
inline void packetCells(FrameBuffer &fb, int x, int y, const uint8_t *p, uint8_t n, const char *title) {
  const ad::Parsed ps = ad::split(p, n);
  char v[40];
  snprintf(v, sizeof(v), "%s %u/31", title, n);
  small(fb, x, y, pal::muted, v);
  for (int i = 0; i < 31; i++) {
    uint16_t c = pal::dim;
    if (i < n) {
      c = pal::muted;
      for (int f = 0; f < ps.count; f++) {
        const ad::Field &fl = ps.fields[f];
        if (i >= fl.offset - 2 && i < fl.offset + fl.len) c = i < fl.offset ? mix(fieldColour(f), pal::night, 120) : fieldColour(f);
      }
    }
    fb.fillRect(x + 84 + i * 7, y, 6, 7, c);
  }
}

// Each AD structure of a packet as one decoded line.
inline int fields(FrameBuffer &fb, int x, int y, const uint8_t *p, uint8_t n, int maxLines) {
  const ad::Parsed ps = ad::split(p, n);
  for (int f = 0; f < ps.count && maxLines > 0; f++, maxLines--, y += 11) {
    const ad::Field &fl = ps.fields[f];
    const uint8_t *d = p + fl.offset;
    char v[56];
    switch (fl.type) {
      case ad::type::kFlags:
        snprintf(v, sizeof(v), "Flags %02X:%s%s", d[0], d[0] & 0x02 ? " discoverable" : d[0] & 0x01 ? " limited" : "", d[0] & 0x04 ? ", LE only" : "");
        break;
      case ad::type::kName:
      case ad::type::kShortName: snprintf(v, sizeof(v), "%s \"%.*s\"", ad::typeName(fl.type), std::min<int>(fl.len, 26), reinterpret_cast<const char *>(d)); break;
      case ad::type::kTxPower: snprintf(v, sizeof(v), "TX power %d dBm", int8_t(d[0])); break;
      case ad::type::kAppearance: snprintf(v, sizeof(v), "Appearance %04X: %s", ad::le16(d), ad::kindName(ad::kindFromAppearance(ad::le16(d)))); break;
      case ad::type::kManufacturer: {
        const uint16_t id = fl.len >= 2 ? ad::le16(d) : 0;
        const char *who = ad::companyName(id);
        if (id == 0x004C && fl.len >= 3) snprintf(v, sizeof(v), "Apple: %s (%u B)", ad::appleType(d[2]), fl.len - 2);
        else snprintf(v, sizeof(v), "Maker %04X %s (%u B)", id, who ? who : "", fl.len >= 2 ? fl.len - 2 : 0);
        break;
      }
      case ad::type::kUuid16All:
      case ad::type::kUuid16Some:
      case ad::type::kServiceData16: {
        const uint16_t u = fl.len >= 2 ? ad::le16(d) : 0;
        const char *what = ad::service16Name(u);
        snprintf(v, sizeof(v), "%s %04X %s", fl.type == ad::type::kServiceData16 ? "Data for" : "Service", u, what ? what : "");
        break;
      }
      case ad::type::kUuid128All:
      case ad::type::kUuid128Some:
        snprintf(v, sizeof(v), "Service %02x%02x%02x%02x-... (128-bit)", d[15], d[14], d[13], d[12]);
        break;
      default: snprintf(v, sizeof(v), "%02X %s (%u B)", fl.type, ad::typeName(fl.type), fl.len); break;
    }
    fb.fillRect(x, y + 1, 4, 5, fieldColour(f));
    small(fb, x + 8, y, pal::ink, v);
  }
  if (ps.malformed && maxLines > 0) small(fb, x + 8, y, pal::coral, "malformed: a length runs past the end"), y += 11;
  return y;
}

inline void inspect(FrameBuffer &fb, const ble::Heard *h, const b1::Settings &set) {
  if (!h) {
    small(fb, 8, 50, pal::muted, "Pick a device: double-click on the list view,");
    small(fb, 8, 62, pal::muted, "or type pick <n> (the number on the list).");
    return;
  }
  char addr[18], v[60];
  h->addrText(addr, sizeof(addr));
  bold(fb, 6, 48, kindColour(h->kind), h->label());
  snprintf(v, sizeof(v), "%s  %s  %s%s", addr, ad::addrKindName(h->addrKind()), h->connectable ? "connectable" : "broadcast only",
           h->scanResponse ? " +rsp" : "");
  small(fb, 6, 54, pal::muted, v);
  snprintf(v, sizeof(v), "%d dBm (avg %d) ~%.1f m, %lu pkts, every %lu ms", h->rssi, int(h->rssiAvg), ad::distanceMeters(int(h->rssiAvg), set.rssiAt1m),
           static_cast<unsigned long>(h->packets), static_cast<unsigned long>(h->lastInterval));
  small(fb, 6, 64, pal::ink, v);
  packetCells(fb, 6, 78, h->adv, h->advLen, "advert");
  int y = fields(fb, 6, 90, h->adv, h->advLen, h->rspLen ? 3 : 6);
  if (h->rspLen) {
    packetCells(fb, 6, y + 2, h->rsp, h->rspLen, "scan rsp");
    fields(fb, 6, y + 14, h->rsp, h->rspLen, 3);
  }
}

inline void air(FrameBuffer &fb, const b1::AirHistory &hist, const ble::Heard *rows, int n, const b1::Settings &set, bool scanning) {
  // Packets per second, last 60 s, as bars; the device count as a line over them.
  const int x0 = 6, y0 = 120, w = 180, h = 74;
  uint16_t peak = 10;
  for (int i = 0; i < b1::AirHistory::kN; i++) peak = std::max(peak, hist.ppsAt(i));
  uint8_t peakDev = 4;
  for (int i = 0; i < b1::AirHistory::kN; i++) peakDev = std::max(peakDev, hist.devicesAt(i));
  small(fb, x0, 34, pal::muted, "packets / s, last minute");
  fb.drawFastHLine(x0, y0, w, pal::dim);
  int lastX = -1, lastY = 0;
  for (int i = 0; i < b1::AirHistory::kN; i++) {
    const int x = x0 + i * 3;
    const int bh = hist.ppsAt(i) * h / peak;
    fb.fillRect(x, y0 - bh, 2, bh, mix(pal::teal, pal::night, 90));
    const int dy = y0 - hist.devicesAt(i) * h / peakDev;
    if (lastX >= 0) fb.drawLine(lastX, lastY, x, dy, pal::amber);
    lastX = x, lastY = dy;
  }
  char v[64];
  snprintf(v, sizeof(v), "peak %u/s", peak);
  small(fb, x0, y0 + 4, pal::teal, v);
  snprintf(v, sizeof(v), "devices (max %u)", peakDev);
  small(fb, x0 + 80, y0 + 4, pal::amber, v);
  snprintf(v, sizeof(v), "%s, %u/%u ms, %u%% listening", scanning ? (set.active ? "active" : "passive") : "paused", set.windowMs, set.intervalMs,
           set.windowMs * 100 / set.intervalMs);
  small(fb, x0, y0 + 16, pal::muted, v);

  // Right: address types. Most phones hide behind private addresses that change every ~15 min.
  int counts[4] = {};
  for (int i = 0; i < n; i++) counts[static_cast<int>(rows[i].addrKind())]++;
  small(fb, 200, 34, pal::muted, "address types");
  static const uint16_t col[] = {pal::ink, pal::teal, kViolet, pal::muted};
  for (int k = 0; k < 4; k++) {
    const int y = 46 + k * 22;
    snprintf(v, sizeof(v), "%s  %d", ad::addrKindName(static_cast<ad::AddrKind>(k)), counts[k]);
    small(fb, 200, y, pal::muted, v);
    fb.drawRect(200, y + 9, 112, 6, pal::dim);
    fb.fillRect(200, y + 9, n ? counts[k] * 112 / n : 0, 6, col[k]);
  }
  small(fb, 200, 136, kViolet, "rpa = a phone hiding");
}

}  // namespace b1v

// B1's ears: a continuous scan that feeds the device table, the per-second air statistics, and
// the "watch" mode that prints every packet of one device (that's how you see its interval).
#pragma once

#include <NimBLEDevice.h>

#include "ble_link.h"
#include "scan_table.h"

namespace b1 {

struct Settings {
  bool active = true;      // ask every device for its scan response too
  uint16_t intervalMs = 100;  // how often the radio starts listening
  uint16_t windowMs = 100;    // and for how long: window/interval = duty cycle
  int nearDbm = -127;      // hide devices weaker than this (-127 = show all)
  int rssiAt1m = -59;      // calibration for the distance guess
};

// The device on the inspect view, by address (rows move around as RSSI changes).
struct Pick {
  uint8_t addr[6] = {};
  uint8_t type = 0;
  bool set = false;
  bool matches(const ble::Heard &h) const { return set && h.addrType == type && memcmp(h.addr, addr, 6) == 0; }
  void take(const ble::Heard &h) {
    memcpy(addr, h.addr, 6);
    type = h.addrType;
    set = true;
  }
};

class Listener : public NimBLEScanCallbacks {
 public:
  ble::ScanTable table;
  Settings settings;

  void begin() {
    NimBLEScan *scan = NimBLEDevice::getScan();
    // wantDuplicates = true: report every packet, not just the first per device, so RSSI stays live.
    scan->setScanCallbacks(this, true);
    // Keep nothing inside NimBLE: our table is the record.
    scan->setMaxResults(0);
    start();
  }

  void start() {
    NimBLEScan *scan = NimBLEDevice::getScan();
    scan->stop();
    scan->setActiveScan(settings.active);
    scan->setInterval(settings.intervalMs);
    scan->setWindow(settings.windowMs);
    // duration 0 = scan until told to stop.
    if (scan->start(0, false, true)) {
      ble::link().edit([](ble::LinkState &s) { s.radio = ble::Radio::Scanning, s.scanning = true; });
      BLE_NOTE(Good, "%s scan, %u/%u ms (%u%% listening)", settings.active ? "active" : "passive", settings.windowMs, settings.intervalMs,
               settings.windowMs * 100 / settings.intervalMs);
    } else {
      BLE_NOTE(Bad, "the scan did not start");
    }
  }

  void stop() {
    NimBLEDevice::getScan()->stop();
    ble::link().edit([](ble::LinkState &s) { s.radio = ble::Radio::Off, s.scanning = false; });
    BLE_NOTE(Info, "scan stopped");
  }

  bool scanning() { return NimBLEDevice::getScan()->isScanning(); }

  void watch(const Pick &p) {
    portENTER_CRITICAL(&lock_);
    watch_ = p;
    watchLast_ = 0;
    portEXIT_CRITICAL(&lock_);
  }
  bool watching() {
    portENTER_CRITICAL(&lock_);
    const bool w = watch_.set;
    portEXIT_CRITICAL(&lock_);
    return w;
  }

  // NimBLE task: every packet heard.
  void onResult(const NimBLEAdvertisedDevice *d) override {
    table.record(d);
    portENTER_CRITICAL(&lock_);
    const bool watched = watch_.set && watch_.type == d->getAddress().getType() && memcmp(watch_.addr, d->getAddress().getVal(), 6) == 0;
    const uint32_t now = millis(), gap = watchLast_ ? now - watchLast_ : 0;
    if (watched) watchLast_ = now;
    portEXIT_CRITICAL(&lock_);
    if (watched) BLE_NOTE(Rx, "+%4lu ms  %d dBm  %u B%s", static_cast<unsigned long>(gap), d->getRSSI(), d->getPayload().size(),
                          d->getPayload().size() > d->getAdvLength() ? " +scan rsp" : "");
  }

  void onScanEnd(const NimBLEScanResults &, int reason) override {
    ble::link().edit([](ble::LinkState &s) { s.radio = ble::Radio::Off, s.scanning = false; });
    BLE_NOTE(Warn, "scan ended (reason %d)", reason);
  }

 private:
  portMUX_TYPE lock_ = portMUX_INITIALIZER_UNLOCKED;
  Pick watch_;
  uint32_t watchLast_ = 0;
};

// Packets per second and devices in range, once a second for the last minute.
struct AirHistory {
  static constexpr int kN = 60;
  uint16_t pps[kN] = {};
  uint8_t devices[kN] = {};
  int head = 0;
  uint32_t lastPackets = 0, at = 0;

  void tick(ble::ScanTable &t, int inRange) {
    const uint32_t now = millis();
    if (now - at < 1000) return;
    at = now;
    const uint32_t p = t.packets();
    pps[head % kN] = uint16_t(std::min<uint32_t>(p - lastPackets, 65535));
    devices[head % kN] = uint8_t(std::min(inRange, 255));
    lastPackets = p;
    head++;
  }
  // i = 0 is the oldest of the last kN seconds.
  uint16_t ppsAt(int i) const { return head < kN ? (i < head ? pps[i] : 0) : pps[(head + i) % kN]; }
  uint8_t devicesAt(int i) const { return head < kN ? (i < head ? devices[i] : 0) : devices[(head + i) % kN]; }
  uint16_t latest() const { return head ? pps[(head - 1) % kN] : 0; }
};

}  // namespace b1

// The shell every Bluetooth LE lab (B1-B8) shares: the screen with its status bar, the push button
// and BOOT, the on-board LED, serial commands, and printing the activity log.
//
// A lab is a BleLabSpec: its views (each one a draw function, plus what a double-click does there),
// its serial commands, and three hooks: setup() once NimBLE is running, tick() on every loop, and
// gesture() to give the button a lab-specific meaning. Each src/ble-lab-bN/main.cpp is that list.
//
// Button or BOOT, by default: click = next view · double-click = this view's action · long press =
// the lab's long action. While a numeric comparison waits: click = yes, long press = no.
// On-board LED, unless the lab claims it: breathing blue = advertising · cyan pulse = scanning ·
// steady blue = connected · violet = encrypted · amber blink = a passkey waits · white blink = data.
#pragma once

#include <Arduino.h>
#include <NimBLEDevice.h>

#include "ble_link.h"
#include "ble_views.h"
#include "button.h"
#include "display.h"
#include "pins.h"

class BleLab;

enum class Gesture : uint8_t { Click, DoubleClick, LongPress };

struct BleCommand {
  const char *name;  // the first word you type
  const char *args;  // for help, e.g. "<dBm>"
  const char *what;  // one line for help
  void (*run)(BleLab &lab, const String &arg, const String &lower);
};

struct BleView {
  const char *name;  // "radar"
  void (*draw)(BleLab &lab, FrameBuffer &fb, float t);
  const char *action;  // the command line a double-click runs on this view, or nullptr
};

struct BleLabSpec {
  const char *env;         // "ble-lab-b1"
  const char *id;          // "B1"
  const char *title;       // "Listen"
  const char *deviceName;  // what phones see: "Bench B3"
  const BleView *views;
  int viewCount;
  int startView;
  const BleCommand *commands;
  int commandCount;
  void (*setup)(BleLab &lab) = nullptr;  // after NimBLE is initialised
  void (*tick)(BleLab &lab) = nullptr;   // every loop, before drawing
  // First say on every gesture. Return true when handled, false for the default.
  bool (*gesture)(BleLab &lab, Gesture g, bool external) = nullptr;
  const char *longAction = nullptr;  // the command line a long press runs by default
};

class BleLab {
 public:
  explicit BleLab(const BleLabSpec &spec) : spec_(spec), view_(spec.startView) {}

  void begin() {
    Serial.begin(115200);
    delay(1500);
    if (!display_.begin()) {
      log_e("No memory for the frame buffer. Stopping.");
      return;
    }
    rgbLedWrite(PIN_RGB, 0, 0, 0);
    external_.begin();
    boot_.begin();
    if (!NimBLEDevice::init(spec_.deviceName)) {
      log_e("NimBLE did not start. Stopping.");
      return;
    }
    Serial.printf("\n%s: NimBLE %s up, address %s, TX power %d dBm\n", spec_.env, NimBLEDevice::getVersion(),
                  NimBLEDevice::getAddress().toString().c_str(), NimBLEDevice::getPower());
    if (spec_.setup) spec_.setup(*this);
    printHelp();
  }

  void loop() {
    FrameBuffer &fb = display_.fb();
    if (fb.pixels() == nullptr) {
      delay(1000);
      return;
    }
    pollSerial();
    handleButton(external_, true);
    handleButton(boot_, false);
    measureRssi();
    if (spec_.tick) spec_.tick(*this);
    link_ = ble::link().get();
    printActivity();
    showLed();

    const float t = millis() / 1000.0f;
    const BleView &v = spec_.views[view_];
    fb.fillScreen(pal::night);
    v.draw(*this, fb, t);
    if (passkeyShowing()) bv::passkey(fb, link_, t);
    bv::header(fb, spec_.id, v.name, view_, spec_.viewCount, link_, t);
    char hint[40];
    if (passkeyShowing() && link_.passkeyCompare) snprintf(hint, sizeof(hint), "click = yes, long = no");
    else if (v.action) snprintf(hint, sizeof(hint), "2x: %s", v.action);
    else snprintf(hint, sizeof(hint), "click: next view");
    bv::footer(fb, hint);
    display_.push();
  }

  // ---- For views and commands ------------------------------------------------------------------

  const ble::LinkState &state() const { return link_; }
  const BleLabSpec &spec() const { return spec_; }
  int view() const { return view_; }

  void setView(int v) {
    view_ = (v % spec_.viewCount + spec_.viewCount) % spec_.viewCount;
    log_i("view %d: %s", view_ + 1, spec_.views[view_].name);
  }
  void showView(const char *name) {
    for (int i = 0; i < spec_.viewCount; i++)
      if (strcmp(spec_.views[i].name, name) == 0) return setView(i);
  }

  // The lab drives the on-board LED itself (B3's LED characteristic); false hands it back.
  void claimLed(bool claimed) {
    ledClaimed_ = claimed;
    ledShown_ = 0xFFFFFFFF;
  }

  // log_w is a macro that can't be returned from a void function; this can.
  [[gnu::format(printf, 2, 3)]] void warn(const char *fmt, ...) {
    char text[120];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(text, sizeof(text), fmt, ap);
    va_end(ap);
    log_w("%s", text);
  }

  // Parse a number argument; false when it is missing, not a number or out of range.
  static bool number(const String &arg, long lo, long hi, long &out) {
    if (arg.isEmpty()) return false;
    for (size_t i = 0; i < arg.length(); i++)
      if (!isDigit(arg[i]) && !(i == 0 && arg[i] == '-')) return false;
    out = arg.toInt();
    return out >= lo && out <= hi;
  }

  void runLine(const String &raw) {
    String line = raw;
    line.trim();
    if (line.isEmpty()) return;
    const int sp = line.indexOf(' ');
    String cmd = sp < 0 ? line : line.substring(0, sp);
    String arg = sp < 0 ? String() : line.substring(sp + 1);
    cmd.toLowerCase();
    arg.trim();
    String lower = arg;
    lower.toLowerCase();
    if (cmd == "help" || cmd == "?") return printHelp();
    if (cmd == "view") {
      long n = 0;
      if (!number(arg, 1, spec_.viewCount, n)) return warn("view <1-%d>", spec_.viewCount);
      return setView(n - 1);
    }
    if (cmd == "status") return printStatus();
    if (cmd == "power") return power(arg);
    for (int i = 0; i < spec_.commandCount; i++)
      if (cmd == spec_.commands[i].name) return spec_.commands[i].run(*this, arg, lower);
    log_w("unknown command '%s' in %s (type help)", line.c_str(), spec_.env);
  }

 private:
  bool passkeyShowing() const { return link_.passkey != 0 && millis() - link_.passkeySince < 30000; }

  void printHelp() {
    Serial.printf("\nBluetooth lab %s %s  (%s)  ·  phones see \"%s\"\n", spec_.id, spec_.title, spec_.env, spec_.deviceName);
    for (int i = 0; i < spec_.commandCount; i++) {
      const BleCommand &c = spec_.commands[i];
      char usage[40];
      snprintf(usage, sizeof(usage), "%s %s", c.name, c.args);
      Serial.printf("  %-28s %s\n", usage, c.what);
    }
    Serial.printf("  %-28s %s\n", "status", "the radio, the link and its security, in detail");
    Serial.printf("  %-28s %s\n", "power <dBm>", "transmit power: -24 to 20 (default 9)");
    Serial.printf("  %-28s %s\n", "view <n>", "show screen view n");
    Serial.print("Views:");
    for (int i = 0; i < spec_.viewCount; i++)
      Serial.printf(" %d %s%s", i + 1, spec_.views[i].name, i + 1 < spec_.viewCount ? " ·" : "\n");
    Serial.println("Button (GPIO 5, optional) or BOOT: click = next view, double-click = the view's action");
  }

  void printStatus() {
    const ble::LinkState s = ble::link().get();
    Serial.printf("radio %s · this board %s · TX power %d dBm\n", ble::radioName(s.radio), NimBLEDevice::getAddress().toString().c_str(),
                  NimBLEDevice::getPower());
    if (s.radio != ble::Radio::Connected) {
      if (s.lastDisconnect >= 0) Serial.printf("last link ended: 0x%02X %s\n", s.lastDisconnect & 0xFF, ble::disconnectReason(s.lastDisconnect));
      return;
    }
    const ble::Peer &p = s.peer;
    Serial.printf("peer %s%s%s (%s) · we are the %s\n", p.addr, p.idAddr[0] ? " id " : "", p.idAddr, p.name[0] ? p.name : "no name",
                  p.central ? "peripheral" : "central");
    Serial.printf("interval %.2f ms · latency %u · timeout %u ms · MTU %u · PHY %u/%u · RSSI %d dBm\n", p.interval * 1.25f, p.latency,
                  p.timeout * 10, p.mtu, p.txPhy, p.rxPhy, p.rssi);
    Serial.printf("security: %s, %s, %s, key %u bytes\n", p.encrypted ? "encrypted" : "not encrypted",
                  p.authenticated ? "authenticated (MITM)" : "not authenticated", p.bonded ? "bonded" : "not bonded", p.keySize);
    Serial.printf("traffic: rx %lu ops / %lu B · tx %lu ops / %lu B\n", static_cast<unsigned long>(s.rxOps), static_cast<unsigned long>(s.rxBytes),
                  static_cast<unsigned long>(s.txOps), static_cast<unsigned long>(s.txBytes));
  }

  void power(const String &arg) {
    long dbm = 0;
    if (!number(arg, -24, 20, dbm)) return warn("power <dBm>, -24 to 20. Now %d dBm", NimBLEDevice::getPower());
    if (!NimBLEDevice::setPower(int8_t(dbm))) return warn("the radio refused %ld dBm", dbm);
    BLE_NOTE(Info, "TX power %d dBm", NimBLEDevice::getPower());
  }

  void pollSerial() {
    static String buffer;
    while (Serial.available()) {
      const char c = Serial.read();
      if (c == '\n' || c == '\r') {
        if (!buffer.isEmpty()) runLine(buffer);
        buffer = "";
      } else if (c == 0x08 || c == 0x7F) {
        if (!buffer.isEmpty()) buffer.remove(buffer.length() - 1);
      } else if (uint8_t(c) < 0x20) {
        // Other control characters (arrow keys send escape sequences): ignore.
      } else if (buffer.length() < 120) {
        buffer += c;
      }
    }
  }

  void handleButton(Button &b, bool external) {
    Gesture g;
    switch (b.poll()) {
      case Button::Event::Click: g = Gesture::Click; break;
      case Button::Event::DoubleClick: g = Gesture::DoubleClick; break;
      case Button::Event::LongPress: g = Gesture::LongPress; break;
      default: return;
    }
    if (spec_.gesture && spec_.gesture(*this, g, external)) return;
    switch (g) {
      case Gesture::Click: setView(view_ + 1); break;
      case Gesture::DoubleClick:
        if (spec_.views[view_].action) {
          Serial.printf("> %s   (double-click)\n", spec_.views[view_].action);
          runLine(spec_.views[view_].action);
        }
        break;
      case Gesture::LongPress:
        if (spec_.longAction) {
          Serial.printf("> %s   (long press)\n", spec_.longAction);
          runLine(spec_.longAction);
        }
        break;
    }
  }

  // RSSI of a live link: the controller measures it on every connection event; we ask once a second.
  void measureRssi() {
    const ble::LinkState &s = link_;
    if (s.radio != ble::Radio::Connected || millis() - rssiAt_ < 1000) return;
    rssiAt_ = millis();
    int8_t rssi = 0;
    if (ble_gap_conn_rssi(s.peer.handle, &rssi) == 0) ble::link().edit([&](ble::LinkState &st) { st.peer.rssi = rssi; });
  }

  // New activity lines go to serial from here, in order, never from the NimBLE task.
  void printActivity() {
    ble::Activity &a = ble::activity();
    const uint32_t head = a.head();
    if (printed_ + ble::Activity::kSize < head) {
      Serial.printf("  ... %lu lines skipped\n", static_cast<unsigned long>(head - ble::Activity::kSize - printed_));
      printed_ = head - ble::Activity::kSize;
    }
    ble::ActEntry e;
    for (; printed_ < head; printed_++)
      if (a.get(printed_, e)) Serial.printf("  %s %s\n", bv::actMark(e.kind), e.text);
  }

  void showLed() {
    if (ledClaimed_) return;
    const uint32_t now = millis();
    const uint32_t traffic = link_.rxOps + link_.txOps;
    if (traffic != traffic_) traffic_ = traffic, flashUntil_ = now + 60;
    // Brightness in 12 steps, so the LED (a whole WS2812 frame per write) is only rewritten on a change.
    const float wave = 0.5f + 0.5f * sinf(now / 1000.0f * 3.1416f);
    const uint8_t breathe = uint8_t(int(wave * 11) * 8 + 6);
    uint8_t r = 0, g = 0, b = 0;
    if (passkeyShowing()) r = (now / 250) & 1 ? 120 : 0, g = r / 2;
    else if (now < flashUntil_) r = 120, g = 120, b = 120;
    else switch (link_.radio) {
      case ble::Radio::Off: break;
      case ble::Radio::Scanning: g = breathe / 2, b = breathe / 2; break;
      case ble::Radio::Advertising: b = breathe; break;
      case ble::Radio::Connecting: r = 60, g = 40; break;
      case ble::Radio::Connected:
        if (link_.peer.encrypted) r = 50, b = 90;
        else b = 90;
        break;
    }
    const uint32_t colour = (uint32_t(r) << 16) | (uint32_t(g) << 8) | b;
    if (colour == ledShown_) return;
    ledShown_ = colour;
    rgbLedWrite(PIN_RGB, r, g, b);
  }

  const BleLabSpec &spec_;
  Display display_;
  Button external_{PIN_BUTTON, "button"};
  Button boot_{PIN_BOOT_BTN, "BOOT"};
  ble::LinkState link_;
  int view_;
  bool ledClaimed_ = false;
  uint32_t ledShown_ = 0xFFFFFFFF, flashUntil_ = 0, traffic_ = 0, rssiAt_ = 0, printed_ = 0;
};

// The advertising packet, byte by byte. No Arduino and no radio here, so kit/test/host/ble_ad_test.cpp
// checks it on the Mac.
//
// An advertisement is at most 31 bytes (legacy advertising) made of AD structures:
//
//   [len][type][data ...] [len][type][data ...] ...
//
// len counts the type byte plus the data. 02 01 06 = 2 bytes follow, type 01 (Flags), value 06
// (LE General Discoverable + BR/EDR not supported). A scan response is a second packet of 31
// bytes in the same format, sent only when a scanner asks for it (an active scan).
#pragma once

#include <math.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>

namespace ad {

// ---- Splitting a packet ------------------------------------------------------------------------

struct Field {
  uint8_t type = 0;
  uint8_t offset = 0;  // where the data starts (after len and type)
  uint8_t len = 0;     // data bytes only
};

struct Parsed {
  Field fields[16];
  int count = 0;
  bool malformed = false;  // a length that runs past the end of the packet
};

inline Parsed split(const uint8_t *p, size_t n) {
  Parsed out;
  size_t i = 0;
  while (i < n && out.count < 16) {
    const uint8_t len = p[i];
    if (len == 0) break;  // padding: the rest of the packet is empty
    if (i + 1 + len > n) {
      out.malformed = true;
      break;
    }
    Field &f = out.fields[out.count++];
    f.type = p[i + 1];
    f.offset = uint8_t(i + 2);
    f.len = uint8_t(len - 1);
    i += 1 + len;
  }
  return out;
}

inline const Field *find(const Parsed &ps, uint8_t type) {
  for (int i = 0; i < ps.count; i++)
    if (ps.fields[i].type == type) return &ps.fields[i];
  return nullptr;
}

// ---- Names -----------------------------------------------------------------------------------

namespace type {
constexpr uint8_t kFlags = 0x01, kUuid16Some = 0x02, kUuid16All = 0x03, kUuid128Some = 0x06, kUuid128All = 0x07;
constexpr uint8_t kShortName = 0x08, kName = 0x09, kTxPower = 0x0A, kConnInterval = 0x12;
constexpr uint8_t kServiceData16 = 0x16, kAppearance = 0x19, kAdvInterval = 0x1A, kUri = 0x24;
constexpr uint8_t kManufacturer = 0xFF;
}  // namespace type

inline const char *typeName(uint8_t t) {
  switch (t) {
    case 0x01: return "Flags";
    case 0x02: return "16-bit services (some)";
    case 0x03: return "16-bit services";
    case 0x04: return "32-bit services (some)";
    case 0x05: return "32-bit services";
    case 0x06: return "128-bit services (some)";
    case 0x07: return "128-bit services";
    case 0x08: return "Short name";
    case 0x09: return "Name";
    case 0x0A: return "TX power";
    case 0x0D: return "Class of device";
    case 0x10: return "Device ID";
    case 0x12: return "Wanted conn. interval";
    case 0x14: return "Solicits 16-bit";
    case 0x15: return "Solicits 128-bit";
    case 0x16: return "Service data";
    case 0x17: return "Target address";
    case 0x19: return "Appearance";
    case 0x1A: return "Adv. interval";
    case 0x1B: return "LE address";
    case 0x1C: return "LE role";
    case 0x20: return "Service data 32";
    case 0x21: return "Service data 128";
